SELECT `app_id` AS appId, `space_id` AS spaceId, `title`, `parent_node_token` AS parentNodeToken, `node_token` AS nodeToken, `obj_token` AS objToken, `obj_type` AS objType, `update_time` AS updateTime, `knowledge_document_type_uuid` AS knowledgeDocumentTypeUuid, `knowledge_document_id` AS knowledgeDocumentId, `knowledge_document_version_id` AS knowledgeDocumentVersionId, `status`, `config` AS configStr, `lcu`, `lcd` FROM `knowledge_feishu_document_mapping`
`space_id` = #{spaceId}
AND `status` = #{status}
AND ( `title` LIKE CONCAT('%', #{keyword}, '%') OR `node_token` LIKE CONCAT('%', #{keyword}, '%') OR `obj_token` LIKE CONCAT('%', #{keyword}, '%') OR `obj_type` LIKE CONCAT('%', #{keyword}, '%') OR `config` LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY `update_time` DESC, `lcd` DESC LIMIT #{startNum}, #{pageSize}

